selector_to_html = {"a[href=\"#flaggems\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagGems \u7b80\u4ecb<a class=\"headerlink\" href=\"#flaggems\" title=\"Link to this heading\">#</a></h1><p><a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagGems\"><a data-lightbox=\"image-set\" href=\"https://img.shields.io/badge/GitHub-flagos--ai/FlagGems-blue\">\n<img alt=\"GitHub\" src=\"https://img.shields.io/badge/GitHub-flagos--ai/FlagGems-blue\"/></a>\n</a>\n<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagGems/blob/master/LICENSE\"><a data-lightbox=\"image-set\" href=\"https://img.shields.io/badge/License-Apache%202.0-green\">\n<img alt=\"License\" src=\"https://img.shields.io/badge/License-Apache%202.0-green\"/></a>\n</a></p>", "a[href=\"references/changelog.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u53d8\u66f4\u5386\u53f2<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><h2>v5.4<a class=\"headerlink\" href=\"#v5-4\" title=\"Link to this heading\">#</a></h2><p><strong>\u53d1\u5e03\u65e5\u671f</strong>\uff1a2026-09-28</p>", "a[href=\"contribution/overview.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u6982\u8ff0<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>\u5728\u62c9\u53d6\u8bf7\u6c42\uff08Pull Request\uff09\u4e2d\uff0c\u8d21\u732e\u8005\u5e94\u8be5\u5c31\u6240\u63d0\u8bae\u7684\u53d8\u66f4\u7ed9\u51fa\u63cf\u8ff0\uff0c\u5305\u62ec\u53d8\u66f4\u7684\u539f\u56e0\u3002\n\u5728\u9700\u8981\u7684\u60c5\u51b5\u4e0b\uff0c\u8bf7\u4e00\u5e76\u63d0\u4ea4\u5355\u5143\u6d4b\u8bd5\u7528\u4f8b\u3002\n\u5728\u62c9\u53d6\u8bf7\u6c42\u88ab\u6700\u7ec8\u5408\u5165\u4e4b\u524d\uff0c\u9700\u8981<strong>\u4e00\u4e2a\u9879\u76ee\u6210\u5458</strong>\u7684\u6279\u51c6\u3002\n\u6b64\u5916\uff0c\u8fd9\u7c7b\u62c9\u53d6\u8bf7\u6c42\u4e5f\u5fc5\u987b\u901a\u8fc7\u6301\u7eed\u96c6\u6210\uff08Continuous Integration\uff0cCI\uff09\u6d4b\u8bd5\u3002</p>", "a[href=\"overview/features.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u529f\u80fd\u7279\u6027\u6982\u89c8<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><h2>\u4e30\u5bcc\u7684\u7b97\u5b50\u96c6\u5408<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p><em>FlagGems</em> \u7684\u4e00\u5927\u7279\u6027\u662f\u63d0\u4f9b\u4e30\u5bcc\u7684 PyTorch \u517c\u5bb9\u7b97\u5b50\u96c6\u5408\u3002\n\u53c2\u9605<a class=\"reference internal\" href=\"references/operators.html\"><span class=\"doc std std-doc\">\u652f\u6301\u7684\u7b97\u5b50</span></a>\u548c\n<a class=\"reference internal\" href=\"references/experimental.html\"><span class=\"doc std std-doc\">\u5b9e\u9a8c\u6027\u7b97\u5b50</span></a>\n\u9875\u9762\u4e86\u89e3\u6b63\u5f0f\u652f\u6301\u7684\u7b97\u5b50\u96c6\u5408\u4ee5\u53ca\u5f53\u524d\u5904\u4e8e\u5b9e\u9a8c\u9636\u6bb5\u7684\u5176\u4ed6\u7b97\u5b50\u3002</p>", "a[href=\"overview/platforms.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u652f\u6301\u7684\u786c\u4ef6\u5e73\u53f0<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p><em>FlagGems</em> \u652f\u6301\u8d85\u8fc7 10 \u79cd\u4e0d\u540c\u540e\u7aef\u786c\u4ef6\u5e73\u53f0\u3002\u76ee\u524d\u652f\u6301\u7684\u5e73\u53f0\u53ca\u8fd9\u4e9b\u5e73\u53f0\u7684\u80fd\u529b\u5217\u4e3e\u5982\u4e0b\uff1a</p>", "a[href=\"references/operators.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u7b97\u5b50\u5217\u8868<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u53c2\u4e0e\u5f00\u53d1<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><p>\u5982\u679c\u4f60\u5bf9 <em>FlagGems</em> \u9879\u76ee\u7684\u613f\u666f\u611f\u5174\u8da3\uff0c\u613f\u610f\u53c2\u4e0e\u5176\u5f00\u53d1\u6d3b\u52a8\uff0c\n\u8bf7\u9605\u8bfb<a class=\"reference internal\" href=\"contribution/overview.html\"><span class=\"doc std std-doc\">\u8d21\u732e\u6307\u5357</span></a> \u5c0f\u8282\u3002\n\u6211\u4eec\u6b22\u8fce\u4efb\u4f55\u5f62\u5f0f\u7684\u8d21\u732e\u3002</p>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u4e0b\u4e00\u6b65<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u8054\u7cfb\u6211\u4eec<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2><p>\u5982\u679c\u4f60\u5bf9 <em>FlagGems</em> \u6709\u4efb\u4f55\u95ee\u9898\uff0c\u8bf7\u5728 GitHub \u4ee3\u7801\u4ed3\u5e93\u4e0a\u767b\u8bb0\u4f60\u7684\u95ee\u9898\uff0c\n\u6216\u8005\u901a\u8fc7 <a href=\"mailto:flaggems@baai.ac.cn\">flaggems@baai.ac.cn</a>\n\u90ae\u7bb1\u4e0e\u6211\u4eec\u8054\u7cfb\u3002</p><p>\u6211\u4eec\u8fd8\u4e3a <em>FlagGems</em> \u521b\u5efa\u4e86\u5fae\u4fe1\u7fa4\u3002\u4f60\u53ef\u4ee5\u5fae\u4fe1\u626b\u63cf\u4e0b\u9762\u7684\u4e8c\u7ef4\u7801\uff0c\u53c2\u4e0e\u7fa4\u804a\u3002\n\u8981\u60f3\u4e86\u89e3\u9879\u76ee\u7684\u6700\u65b0\u8fdb\u5c55\u3001\u65b0\u7248\u672c\u7684\u89c4\u5212\u7279\u6027\uff0c\u6216\u8005\u63d0\u51fa\u4efb\u4f55\u95ee\u9898\u4e0e\u5efa\u8bae\uff0c\n\u8bf7\u8003\u8651\u52a0\u5165\u6211\u4eec\uff01</p>", "a[href=\"#id6\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u8bb8\u53ef\u534f\u8bae<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">#</a></h2><p><em>FlagGems</em> \u9879\u76ee\u4f7f\u7528\n<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagGems/blob/master/LICENSE\">Apache 2.0</a>\n\u8bb8\u53ef\u534f\u8bae\u3002</p>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u652f\u6301\u7684\u6a21\u578b<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2>", "a[href=\"getting-started/install.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5b89\u88c5 FlagGems<a class=\"headerlink\" href=\"#flaggems\" title=\"Link to this heading\">#</a></h1><h2>1. \u73af\u5883\u51c6\u5907<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5173\u4e8e FlagGems<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p><em>FlagGems</em> \u662f\u4e00\u4e2a\u9ad8\u6027\u80fd\u7684\u901a\u7528\u7b97\u5b50\u5e93\uff0c\u4f7f\u7528 <a class=\"reference external\" href=\"https://github.com/openai/triton\">Triton</a>\n\u7f16\u7a0b\u8bed\u8a00\u5b9e\u73b0\u3002\u9879\u76ee\u7684\u76ee\u6807\u662f\u63d0\u4f9b\u4e00\u5957\u6838\u5fc3\uff08kernel\uff09\u51fd\u6570\u6765\u52a0\u901f LLM \u8bad\u7ec3\u4e0e\u63a8\u7406\u3002</p><p>\u901a\u8fc7\u5c06\u81ea\u8eab\u7b97\u5b50\u5b9e\u73b0\u6ce8\u518c\u5230 PyTorch \u7684 ATen \u540e\u7aef\uff0c<em>FlagGems</em> \u53ef\u4ee5\u5b9e\u73b0\u65e0\u7f1d\u7684\u8854\u63a5\uff0c\n\u65b9\u4fbf\u7528\u6237\u5728\u4e0d\u9700\u8981\u4fee\u6539\u81ea\u8eab\u6a21\u578b\u4ee3\u7801\u7684\u524d\u63d0\u4e0b\u8fc1\u79fb\u5230 Triton \u51fd\u6570\u5e93\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
